from taf.sbts.oam.coam.admin.interface import admin
from taf.internal.sbts.admin.exceptions.exception import AdminApiProcedureFailureException

from taf.rfrl.procedures.resources.python.logger import \
    log_result, log_input_and_output, log_operation


@log_input_and_output
def start_5g_downlink_test(connection, distname_realtime, test_model, phys_cell_id, beam_id=None, power_backoff=0, polarization="P_plus45_or_0",
                           ru_mode="NR_Only", codebook_2_antports=0, i11_codebook_4_antports=0, i2_codebook_4_antports=0, i13_codebook_4_antports=0,
                           mimo_rank=1, vswr_monitoring=False, nrarfcn_dl=None, nrarfcn_ul=None, pmax=30, timeout=60, load_type=None,
                           load_level_flat=None, load_level_burst=None, load_level_slot_wise=None, num_of_ssb_beam_pattern_id=None,
                           ssb_beam_pattern_id=None, act_micro_dtx=None):
    """
    Starts 5G Downlink Test Model on NR cell.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param distname_realtime: realtime dist_name object of particular cell,
                              e.g. "/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/NRBTS_R-1/NRCELL_R-1"
    :type distname_realtime: str
    :param test_model: type of downlink test model, one of the following: `TM1_1`, `TM1_2`, `TM2`,
                       `TM2A`, `TM3_1`, `TM3_1A`, `TM3_2`, `TM3_3`, `TM3_1N`
    :type test_model: str
    :param phys_cell_id: physical cell ID of particular cell
    :type phys_cell_id: int or str
    :param beam_id: parameter required to start test model, default None means set beam_id on [0]
    :type beam_id: list or None
    :param power_backoff: parameter required to start test model, default set on 0
    :type power_backoff: int or str
    :param polarization: parameter required to start test model, default set on "P_plus45_or_0"
    :type polarization: str
    :param ru_mode: parameter required to start test model, default set on "NR_Only"
    :type ru_mode: str
    :param codebook_2_antports: parameter required to start test model, default set on 0
    :type codebook_2_antports: int
    :param i11_codebook_4_antports: parameter required to start test model, default set on 0
    :type i11_codebook_4_antports: int
    :param i2_codebook_4_antports: parameter required to start test model, default set on 0
    :type i2_codebook_4_antports: int
    :param i13_codebook_4_antports: parameter required to start test model, default set on 0
    :type i13_codebook_4_antports: int
    :param mimo_rank: parameter required to start test model, default set on 1
    :type mimo_rank: int
    :param vswr_monitoring: enable VSWR monitoring parameter, default set to false.
    :type vswr_monitoring: bool
    :param nrarfcn_dl: parameter NRARFCN downlink [0..3279165], default set to None which means value from the cell config will be used.
    :type nrarfcn_dl: int or str
    :param nrarfcn_ul: parameter NRARFCN uplink [0..3279165], default set to None which means value from the cell config will be used.
    :type nrarfcn_ul: int or str
    :param pmax: pMax parameter on WebM, default set on 30
    :type pmax: int or str
    :param timeout: timeout value in seconds for the start test model operation, default is 60 seconds.
    :type timeout: int or str
    :param load_type: "flatLoad" | "burstLoad" required only when TM1_1_ETSI is set for test_model, default set to None
    :type load_type: str
    :param load_level_flat: "low" | "medium" | "busy" | "full" (required only when "flatLoad" set for "load_type"), default set to None
    :type load_level_flat: str
    :param load_level_burst: "burst_13_5" | "burst_19_2" | "burst_32_7" | "burst_46_2" | "burst_59_6" |
                             "burst_73_1" | "burst_86_5" | "burst_100" (required only when "burstLoad" set for "load_type"), default set to None
    :type load_level_burst: str
    :param load_level_slot_wise: 'load_0_low' | 'load_10' | 'load_30_medium'| 'load_50_busy_hour' | 'load_70'. Required only
                                 when load_level set for loadLevelSlotWise, default set to None
    :type load_level_slot_wise: str
    :param num_of_ssb_beam_pattern_id: "ssb_4" | "ssb_8" | "ssb_32" (required only when "low" set for "load_level_flat".
                                        ssb_4 when FR1<=3GHz ssb_8 when 3 GHz<FR1<6 GHz ssb_32 when FR2. Note: 1 GHz = 1000 MHz), default set to None
    :type num_of_ssb_beam_pattern_id: str
    :param ssb_beam_pattern_id: list of SSB beam pattern IDs, default set to None
    :type ssb_beam_pattern_id: list or None
    :param act_micro_dtx: activate micro DTX parameter, default set to None
    :type act_micro_dtx: bool or None
    :return: dict of formatted test result and result message
             e.g. {"status": "Succeeded", "msg": "Test model has started successfully"}
    :rtype: dict
    """
    if beam_id is None:
        beam_id = [0]
    try:
        adm = admin()
        start_test_response = adm.start_5g_downlink_test(dist_name=distname_realtime,
                                                         test_model=test_model,
                                                         beam_pattern_id=beam_id,
                                                         polarization=polarization,
                                                         power_backoff=int(power_backoff),
                                                         ru_mode=ru_mode,
                                                         phys_cell_id=int(phys_cell_id),
                                                         codebook_2_antports=codebook_2_antports,
                                                         i11_codebook_4_antports=i11_codebook_4_antports,
                                                         i2_codebook_4_antports=i2_codebook_4_antports,
                                                         i13_codebook_4_antports=i13_codebook_4_antports,
                                                         mimo_rank=mimo_rank,
                                                         connection=connection,
                                                         vswr_monitoring=vswr_monitoring,
                                                         nrarfcn_dl=nrarfcn_dl,
                                                         nrarfcn_ul=nrarfcn_ul,
                                                         p_max=pmax,
                                                         timeout=int(timeout),
                                                         load_type=load_type,
                                                         load_level_flat=load_level_flat,
                                                         load_level_burst=load_level_burst,
                                                         load_level_slot_wise=load_level_slot_wise,
                                                         num_of_ssb_beam_pattern_id=num_of_ssb_beam_pattern_id,
                                                         ssb_beam_pattern_id=ssb_beam_pattern_id,
                                                         act_micro_dtx=act_micro_dtx)

        log_operation("Downlink test model has successfully been started.")
        return {"status": "Succeeded",
                "msg": start_test_response}

    except AdminApiProcedureFailureException as exc:
        log_result("Downlink test model start failed.")
        return _parse_admin_api_procedure_failure_exception_message_for_test_model(exc)


