@log_input_and_output
def start_5g_uplink_test(dist_name, frc_index, connection, phys_cell_id, nrarfcn_ul, nrarfcn_dl, timeout=30,
                         beam_pattern_id=None, interval=1, prb_offset=0, ru_mode='NR_only'):
    """
    Starts NR Uplink Test Model on NR cell.

    :param dist_name: cell runtime dist_name,
                      e.g. "/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/NRBTS_R-1/NRCELL_R-1"
    :type dist_name: str
    :param frc_index: name of the FRC index e.g. "G-FR1-A1-1"
    :type frc_index: str
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param phys_cell_id: physical cell ID of particular cell
    :type phys_cell_id: int or str
    :param nrarfcn_ul: NRARFCN uplink [0..3279165], default set to None which means value from the cell config will be used.
    :type nrarfcn_ul: int or str
    :param nrarfcn_dl: NRARFCN downlink [0..3279165], default set to None which means value from the cell config will be used.
    :type nrarfcn_dl: int or str
    :param timeout: timeout value in seconds for the start test model operation, default is 30 seconds.
    :type timeout: int or str
    :param beam_pattern_id: parameter beam_pattern_id, default None means set beam_id on [0]
    :type beam_pattern_id: list or none
    :param interval: parameter reporting time interval, default is 1 second
    :type interval: float or str
    :param prb_offset: parameter prb_offset, default is 0
    :type prb_offset: int or str
    :param ru_mode: parameter ru_mode, one of the following: `NR_Only`, `Customize_1 `, `MSR`, default is 'NR_only'
    :return: dict of formatted test result and result message
             e.g. {"status": "Succeeded", "msg": "Test model has started successfully"}
    :rtype: dict
    """
    if beam_pattern_id is None:
        beam_pattern_id = [0]
    try:
        adm = admin()
        start_test_response = adm.start_5g_uplink_test(dist_name=dist_name,
                                                       frc_index=frc_index,
                                                       beam_pattern_id=beam_pattern_id,
                                                       interval=interval,
                                                       prb_offset=prb_offset,
                                                       ru_mode=ru_mode,
                                                       phys_cell_id=phys_cell_id,
                                                       nrarfcn_ul=nrarfcn_ul,
                                                       nrarfcn_dl=nrarfcn_dl,
                                                       timeout=timeout,
                                                       connection=connection)

        log_operation("NR Uplink test model has successfully been started.")
        return {"status": "Succeeded",
                "msg": start_test_response}

    except AdminApiProcedureFailureException as exc:
        log_result("Uplink test model start failed.")
        return _parse_admin_api_procedure_failure_exception_message_for_test_model(exc)


