@log_input_and_output
def get_5g_uplink_test_results(cell_distname, connection, test_duration=10):
    """
    Gets test results from NR Uplink Test Model

    :param cell_distname: cell runtime dist_name
                          e.g. "/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/NRBTS_R-1/NRCELL_R-1"
    :type cell_distname: str
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param test_duration: default is 10 seconds.
    :type test_duration: int or str
    :return: dict with counter data
    :rtype: dict
    """
    adm = admin()
    test_results = adm.watch_5g_uplink_test_results(nr_cell_rdn=cell_distname,
                                                    connection=connection,
                                                    timeout=int(test_duration),
                                                    get_updates=True)

    return test_results


