@log_input_and_output
def stop_5g_performance_test(connection, cell_dist_name, test_name, timeout=15):
    """
    Stops any 5G performance test
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param cell_dist_name: cell runtime dist_name
    :type cell_dist_name: str
    :param test_name: name of performance test, e.g. PUSCH
    :type test_name: str
    :param timeout: timeout value in seconds for the stop test model operation, default is 15 seconds.
    :type timeout: int or str
    :return: dict of formatted test result and result message,
             e.g. {"status": "Succeeded", "msg": "Test model has stopped successfully"}
    :rtype: dict
    """
    try:
        adm = admin()
        stop_test_response = adm.stop_5g_uplink_ccm_test(connection=connection,
                                                         dist_name=cell_dist_name,
                                                         timeout=int(timeout))

        log_operation("{} performance test has successfully been stopped.".format(test_name))
        return {"status": "Succeeded",
                "msg": stop_test_response}

    except AdminApiProcedureFailureException as exc:
        log_result("{} performance test stop failed.".format(test_name))
        return _parse_admin_api_procedure_failure_exception_message_for_test_model(exc)


@log_input_and_output
def get_5g_performance_test_results(connection, cell_dist_name, timeout=100):
    """
    Gets test results from an ongoing 5G performance test
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param cell_dist_name: cell runtime dist_name
    :type cell_dist_name: str
    :param timeout: timeout value in seconds for get 5g performance test results, default is 100 seconds.
    :type timeout: int or str
    :return: dict with counter data
    :rtype: dict
    """
    adm = admin()
    test_results = adm.watch_5g_uplink_ccm_test_results(connection=connection,
                                                        nr_cell_rdn=cell_dist_name,
                                                        get_updates=True,
                                                        timeout=int(timeout))

    return test_results


def _parse_admin_api_procedure_failure_exception_message_for_test_model(exception_response):
    """
    Parses output message from exception AdminApiProcedureFailureException. Exception is raising when Test Model
    cannot start due to invalid test parameter or BTS configuration.
    :param exception_response: exception message from AdminApiProcedureFailureException
    :type exception_response: str
    :return: dict of formatted exception message with failed status and message with fail reason,
             e.g. : {'status': 'Failed', 'msg': 'ErrorCode: 69'}
    :rtype: dict
    """
    fail_reason = str(exception_response)
    return {"status": "Failed",
            "msg": fail_reason}
